-- Synthetic records, messages and notifications are rolled back. No provider calls.
begin;
create temp table activation_results(check_name text,passed boolean);
do $test$
#variable_conflict use_variable
declare staff uuid;ids uuid[]:='{}';apps uuid[]:='{}';uid uuid;iid uuid;ref text;roles text[];solo_tid uuid;group_tid uuid;blocked_tid uuid;result jsonb;one jsonb;k integer;denied boolean;active_count integer;test_tid uuid;test_actor uuid;meeting_id uuid;evidence_id uuid;task_id uuid;resource_id uuid;meeting_payload jsonb;
begin
 select user_id into staff from private_website_lab.member_roles where role='full_admin' and private_website_lab.permitted(user_id,'operations') limit 1;
 select project_ref,array(select jsonb_array_elements_text(b.roles)) into ref,roles from public.website_project_briefs b where jsonb_typeof(b.roles)='array' and jsonb_array_length(b.roles)>=2 order by project_ref limit 1;
 for k in 1..6 loop
  uid:=gen_random_uuid();insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values(uid,'activation-'||uid||'@example.invalid',now(),'{"full_name":"Synthetic activation member"}');
  insert into public.website_project_interests(user_id,project_ref,participation,primary_role,motivation,contribution,answers,terms_version) values(uid,ref,case when k in (1,6) then 'solo' else 'team' end,roles[1],repeat('fixture ',5),repeat('fixture ',8),jsonb_build_object('commitment_response','yes','coordination_preference',case when k=2 then 'comfortable' else 'contributor' end),'2026-09-03-v1') returning id into iid;
  ids:=array_append(ids,uid);apps:=array_append(apps,iid);
 end loop;
 perform set_config('request.jwt.claim.sub',staff::text,true);
 for k in 1..6 loop perform public.website_lab('review_interest',jsonb_build_object('interest_id',apps[k],'review_status','shortlisted'));end loop;
 solo_tid:=(public.website_lab('form_group',jsonb_build_object('project_ref',ref,'label','[ROLLBACK] Automatic Solo','participation','solo','compatibility_reviewed','true','required_roles',to_jsonb(roles[1:2]),'members',jsonb_build_array(jsonb_build_object('interest_id',apps[1],'role',roles[1]))))->>'team_id')::uuid;
 perform set_config('request.jwt.claim.sub',ids[1]::text,true);
 result:=public.website_lab('respond',jsonb_build_object('team_id',solo_tid,'response','accept','commitment_confirmed','true'));
 if (select status from public.website_project_teams where id=solo_tid)<>'forming' or not (select lab_enabled from public.website_project_teams where id=solo_tid) then raise exception 'Acceptance bypassed checks or failed to prepare Solo workspace';end if;
 if (select admitted_at from public.website_project_team_members where team_id=solo_tid and user_id=ids[1]) is not null then raise exception 'Acceptance inferred repository permission';end if;
 select x into one from jsonb_array_elements(public.website_lab('mine')) x where x->>'team_id'=solo_tid::text;
 if not exists(select 1 from jsonb_array_elements(one->'readiness'->'checks') c where c->>'label'='Repository access checked' and c->>'ready'='false') then raise exception 'Missing member-facing repository blocker';end if;
 denied:=false;begin perform public.website_lab('workspace',jsonb_build_object('team_id',solo_tid));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Ordinary member entered forming Lab';end if;
 insert into activation_results values('one Solo acceptance prepares workspace and shows the real blocker without granting Lab access',true);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 result:=public.website_lab('verify_access',jsonb_build_object('team_id',solo_tid,'user_id',ids[1],'reason','Synthetic repository verification only'));
 if result->'activation'->>'activated'<>'true' or (select status from public.website_project_teams where id=solo_tid)<>'active' then raise exception 'Last readiness check did not open Solo Lab';end if;
 perform public.website_lab('verify_access',jsonb_build_object('team_id',solo_tid,'user_id',ids[1],'reason','Synthetic repeated verification only'));
 if (select count(*) from private_website_lab.audit where team_id=solo_tid and action='automatic_lab_start')<>1 then raise exception 'Automatic activation was duplicated';end if;
 perform set_config('request.jwt.claim.sub',ids[1]::text,true);
 select x into one from jsonb_array_elements(public.website_lab('mine')) x where x->>'team_id'=solo_tid::text;
 if one->>'can_enter'<>'true' then raise exception 'Activated owner still cannot enter';end if;
 perform public.website_lab('discussion',jsonb_build_object('team_id',solo_tid,'project_ref',ref,'body','Synthetic Solo project note after activation.','client_nonce',gen_random_uuid()));
 denied:=false;begin perform public.website_lab('respond',jsonb_build_object('team_id',solo_tid,'response','accept','commitment_confirmed','true'));exception when raise_exception then denied:=true;end;if not denied then raise exception 'A second acceptance was accepted';end if;
 insert into activation_results values('verified Solo Lab opens once without Start or second acceptance; owner can write project notes',true);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 group_tid:=(public.website_lab('form_group',jsonb_build_object('project_ref',ref,'label','[ROLLBACK] Automatic Team','participation','team','compatibility_reviewed','true','nominee_id',ids[2],'required_roles',to_jsonb(roles[1:2]),'members',jsonb_build_array(jsonb_build_object('interest_id',apps[2],'role',roles[1],'roles',to_jsonb(roles[1:2])),jsonb_build_object('interest_id',apps[3],'role',roles[1]),jsonb_build_object('interest_id',apps[4],'role',roles[1]))))->>'team_id')::uuid;
 for k in 2..3 loop perform set_config('request.jwt.claim.sub',ids[k]::text,true);perform public.website_lab('respond',jsonb_build_object('team_id',group_tid,'response','accept','commitment_confirmed','true'));end loop;
 perform set_config('request.jwt.claim.sub',ids[2]::text,true);perform public.website_lab('agree_coordinator',jsonb_build_object('team_id',group_tid));
 perform set_config('request.jwt.claim.sub',staff::text,true);
 for k in 2..3 loop perform public.website_lab('verify_access',jsonb_build_object('team_id',group_tid,'user_id',ids[k],'reason','Synthetic team access check'));end loop;
 if (select status from public.website_project_teams where id=group_tid)<>'forming' then raise exception 'Team started before minimum acceptance';end if;
 perform set_config('request.jwt.claim.sub',ids[4]::text,true);perform public.website_lab('respond',jsonb_build_object('team_id',group_tid,'response','accept','commitment_confirmed','true'));
 if (select status from public.website_project_teams where id=group_tid)<>'forming' then raise exception 'Team started before final repository check';end if;
 perform set_config('request.jwt.claim.sub',staff::text,true);perform public.website_lab('verify_access',jsonb_build_object('team_id',group_tid,'user_id',ids[4],'reason','Synthetic final team access check'));
 if (select status from public.website_project_teams where id=group_tid)<>'active' or (select count(*) from public.website_project_team_members where team_id=group_tid and admitted_at is not null)<>3 then raise exception 'Ready Team not activated with three actual people';end if;
 insert into activation_results values('Team activation preserves headcount, coordinator consent, multi-role coverage and repository checks',true);
 -- Exercise the actual member actions for an active Solo owner and a normal Team contributor.
 for k in 1..2 loop
  test_tid:=case when k=1 then solo_tid else group_tid end;
  test_actor:=case when k=1 then ids[1] else ids[3] end;
  perform set_config('request.jwt.claim.sub',test_actor::text,true);
  result:=public.website_lab('meetings',jsonb_build_object('team_id',test_tid));
  if result->>'can_schedule'<>'true' then raise exception 'Active member cannot schedule meeting: arrangement %',k;end if;
  meeting_payload:=jsonb_build_object('team_id',test_tid,'client_nonce',gen_random_uuid(),'topic','Synthetic full journey meeting','agenda','Review test work only; no real invitations.','starts_at',now()+interval '3 days','ends_at',now()+interval '3 days 30 minutes','time_zone','Europe/London','join_url','https://meet.google.com/abc-defg-hij');
  meeting_id:=(public.website_lab('meeting_save',meeting_payload)->>'meeting_id')::uuid;
  if meeting_id is null or (public.website_lab('meeting_save',meeting_payload)->>'meeting_id')::uuid<>meeting_id then raise exception 'Meeting creation or retry failed';end if;
  perform public.website_lab('meeting_save',meeting_payload||jsonb_build_object('meeting_id',meeting_id,'expected_revision',1,'topic','Updated synthetic journey meeting'));
  if (select topic from private_website_lab.meetings where id=meeting_id)<>'Updated synthetic journey meeting' then raise exception 'Meeting edit not persisted';end if;
  perform public.website_lab('meeting_cancel',jsonb_build_object('team_id',test_tid,'meeting_id',meeting_id,'expected_revision',2));
  if (select status from private_website_lab.meetings where id=meeting_id)<>'cancelled' then raise exception 'Meeting cancellation not persisted';end if;
  evidence_id:=(public.website_lab('add_item',jsonb_build_object('team_id',test_tid,'kind','contribution','title','Synthetic personal delivery evidence','body','I prepared a reproducible analysis and checked the source data.','collaboration','I documented decisions and incorporated review feedback into the work.','url','https://github.com/Mettelo/example-demo'))->>'id')::uuid;
  resource_id:=(public.website_lab('add_item',jsonb_build_object('team_id',test_tid,'kind','resource','title','Synthetic source reference','url','https://www.ons.gov.uk/'))->>'id')::uuid;
  result:=public.website_lab('workspace',jsonb_build_object('team_id',test_tid));
  if not exists(select 1 from jsonb_array_elements(result->'items') x where x->>'id'=evidence_id::text and x->>'author_id'=test_actor::text) or not exists(select 1 from jsonb_array_elements(result->'items') x where x->>'id'=resource_id::text) then raise exception 'Contribution or reference missing from workspace';end if;
  perform public.website_lab('discussion',jsonb_build_object('team_id',test_tid,'project_ref',ref,'body','Synthetic functional journey update.','client_nonce',gen_random_uuid()));
  insert into activation_results values(case when k=1 then 'Solo owner can create, retry, edit and cancel meetings; save own contribution, link and chat' else 'ordinary Team member can create, retry, edit and cancel meetings; save own contribution, link and chat' end,true);
 end loop;
 -- A contributor can update assigned work; the coordinator performs the review.
 perform set_config('request.jwt.claim.sub',ids[2]::text,true);
 task_id:=(public.website_lab('add_item',jsonb_build_object('team_id',group_tid,'kind','task','title','Synthetic end-to-end task','owner_id',ids[3]))->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',ids[3]::text,true);
 perform public.website_lab('task_status',jsonb_build_object('task_id',task_id,'status','in_progress'));
 perform public.website_lab('task_status',jsonb_build_object('task_id',task_id,'status','ready_for_review'));
 perform set_config('request.jwt.claim.sub',ids[2]::text,true);
 perform public.website_lab('task_status',jsonb_build_object('task_id',task_id,'status','done'));
 if (select status from private_website_lab.items where id=task_id)<>'done' then raise exception 'Task did not complete its ownership/review journey';end if;
 insert into activation_results values('task creation, member progress and coordinator completion persist correctly',true);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 perform public.website_lab('offer',jsonb_build_object('team_id',group_tid,'interest_id',apps[5],'role',roles[1]));
 perform set_config('request.jwt.claim.sub',ids[5]::text,true);perform public.website_lab('respond',jsonb_build_object('team_id',group_tid,'response','accept','commitment_confirmed','true'));
 if (select admitted_at from public.website_project_team_members where team_id=group_tid and user_id=ids[5]) is not null then raise exception 'Additional member bypassed admission review';end if;
 denied:=false;begin perform public.website_lab('workspace',jsonb_build_object('team_id',group_tid));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Unadmitted additional member entered active Lab';end if;
 perform set_config('request.jwt.claim.sub',staff::text,true);perform public.website_lab('placement_status',jsonb_build_object('team_id',group_tid,'status','paused','reason','Synthetic deliberate pause'));
 perform set_config('request.jwt.claim.sub',ids[2]::text,true);perform public.website_lab('confirm_commitment',jsonb_build_object('team_id',group_tid));
 if (select status from public.website_project_teams where id=group_tid)<>'paused' then raise exception 'Paused team resumed automatically';end if;
 insert into activation_results values('additional-member admission and intentional pauses remain controlled',true);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 select count(*) into active_count from public.website_project_teams where project_ref=ref and status='active';
 update public.website_project_pilot_settings set max_active_teams=greatest(active_count,1) where project_ref=ref;
 blocked_tid:=(public.website_lab('form_group',jsonb_build_object('project_ref',ref,'label','[ROLLBACK] Capacity Waiting Solo','participation','solo','compatibility_reviewed','true','members',jsonb_build_array(jsonb_build_object('interest_id',apps[6],'role',roles[1]))))->>'team_id')::uuid;
 perform set_config('request.jwt.claim.sub',ids[6]::text,true);perform public.website_lab('respond',jsonb_build_object('team_id',blocked_tid,'response','accept','commitment_confirmed','true'));
 perform set_config('request.jwt.claim.sub',staff::text,true);perform public.website_lab('verify_access',jsonb_build_object('team_id',blocked_tid,'user_id',ids[6],'reason','Synthetic capacity check verification'));
 if (select status from public.website_project_teams where id=blocked_tid)<>'forming' or (select status from public.website_project_team_members where team_id=blocked_tid and user_id=ids[6])<>'confirmed' then raise exception 'Capacity either bypassed or rolled back member acceptance';end if;
 if has_function_privilege('authenticated','private_website_lab.activate_ready_placement(uuid)','EXECUTE') or has_function_privilege('authenticated','private_website_lab.operations_before_ready_activation(text,jsonb)','EXECUTE') then raise exception 'Internal activation helpers exposed';end if;
 insert into activation_results values('capacity blocks activation while preserving acceptance; private helper grants stay closed',true);
end $test$;
select * from activation_results;
rollback;
